{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "For buildings constructed or remodeled after July 1, 2023, but before July 1, 2025, the building must have a clear entry-resistant film on the glass panel of each exterior entry or basement-level window and door. The purpose is to keep people from getting in without authorization by breaking the glass.",
      "rationale": "Conveys the date range, required film, covered glass panels, and unauthorized-entry purpose. The introductory paragraph establishes that public schools, including charter schools, are covered."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "For buildings constructed or remodeled on or after July 1, 2025, the building must have clear window film or security glazing that meets a nationally recognized test standard for resisting forced entry. The bill gives ASTM F3561 as an example. The requirement applies to exterior entries or doors plus adjoining glazing, and to the secure interior vestibules that serve as primary entrances.",
      "rationale": "Conveys the construction or remodeling trigger, date, permitted materials, required performance standard, and covered locations. The introduction supplies the public-school and charter-school scope."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The state-level safety team set up under section 49-6-802 would develop guidelines for complying with the section and update them as needed.",
      "rationale": "Identifies the responsible team and both its guideline-development and ongoing update duties; the preceding sentence identifies the compliance section."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "It would send all of its guidelines to the state fire marshal, who would incorporate them into rules under section 68-120-101.",
      "rationale": "Conveys transmission of all guidelines by the previously identified safety team to the fire marshal for incorporation into rules."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The state fire marshal would be authorized to make rules to carry out the act. These must follow the Uniform Administrative Procedures Act.",
      "rationale": "Conveys the fire marshal's rulemaking authority and the required administrative procedure. The omitted code citation is nonessential."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "For developing guidelines and making rules, the act would take effect when it becomes law. For all other purposes, it would take effect July 1, 2025.",
      "rationale": "Conveys both effective dates and the purposes to which each applies."
    }
  ]
}
